from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
path = ROOT / "tests/ui/files.spec.js"
text = path.read_text(encoding="utf-8")
old = '''  const box = await firstPane.evaluate((el) => {\n    const rects = [...el.querySelectorAll(".file-tile")].map((t) => t.getBoundingClientRect());\n    const grid = el.querySelector(".filegrid").getBoundingClientRect();\n    return {\n      sx: Math.round(rects[0].left + 4),\n      sy: Math.round(grid.bottom - 5),\n      tx: Math.round(rects[1].left + rects[1].width / 2),\n      ty: Math.round(rects[0].top + 4),\n    };\n  });\n\n  await page.mouse.move(box.sx, box.sy);\n  await page.mouse.down();\n  await page.mouse.move((box.sx + box.tx) / 2, (box.sy + box.ty) / 2, { steps: 6 });\n  await page.mouse.move(box.tx, box.ty, { steps: 6 });\n  await page.mouse.up();\n\n  await expect(firstPane.locator(".filepane-selectionbar")).toContainText("2 项已选");\n'''
new = '''  const box = await firstPane.evaluate((el) => {\n    const tiles = [...el.querySelectorAll(".file-tile")];\n    const rects = tiles.map((t) => t.getBoundingClientRect());\n    const grid = el.querySelector(".filegrid").getBoundingClientRect();\n    const body = el.querySelector(".filepane-body").getBoundingClientRect();\n    const sx = Math.round(rects[0].left + 4);\n    const sy = Math.round(grid.bottom - 5);\n    const tx = Math.round(rects[1].left + rects[1].width / 2);\n    const ty = Math.round(rects[0].top + 4);\n    window.__marqueeEvents = [];\n    for (const type of ["mousedown", "mousemove", "mouseup"]) {\n      window.addEventListener(type, (event) => {\n        if (window.__marqueeEvents.length >= 40) return;\n        const target = event.target instanceof Element ? event.target : null;\n        window.__marqueeEvents.push({\n          type,\n          x: event.clientX,\n          y: event.clientY,\n          target: target?.className ?? target?.tagName ?? null,\n          path: target?.closest?.("[data-path]")?.getAttribute("data-path") ?? null,\n        });\n      }, true);\n    }\n    return {\n      sx, sy, tx, ty,\n      body: { top: body.top, bottom: body.bottom, left: body.left, right: body.right },\n      grid: { top: grid.top, bottom: grid.bottom, left: grid.left, right: grid.right },\n      scroll: {\n        top: el.querySelector(".filepane-body").scrollTop,\n        height: el.querySelector(".filepane-body").scrollHeight,\n        client: el.querySelector(".filepane-body").clientHeight,\n      },\n      startHit: (() => {\n        const hit = document.elementFromPoint(sx, sy);\n        return { className: hit?.className ?? null, tag: hit?.tagName ?? null, path: hit?.closest?.("[data-path]")?.getAttribute("data-path") ?? null };\n      })(),\n      endHit: (() => {\n        const hit = document.elementFromPoint(tx, ty);\n        return { className: hit?.className ?? null, tag: hit?.tagName ?? null, path: hit?.closest?.("[data-path]")?.getAttribute("data-path") ?? null };\n      })(),\n      tiles: rects.map((r, index) => ({ index, left: r.left, right: r.right, top: r.top, bottom: r.bottom, path: tiles[index].getAttribute("data-path") })),\n    };\n  });\n  console.log("MARQUEE_GEOMETRY", JSON.stringify(box));\n\n  await page.mouse.move(box.sx, box.sy);\n  await page.mouse.down();\n  await page.mouse.move((box.sx + box.tx) / 2, (box.sy + box.ty) / 2, { steps: 6 });\n  await page.mouse.move(box.tx, box.ty, { steps: 6 });\n  await page.mouse.up();\n\n  console.log("MARQUEE_EVENTS", JSON.stringify(await page.evaluate(() => window.__marqueeEvents)));\n  console.log("MARQUEE_STATE", JSON.stringify(await firstPane.evaluate((el) => ({\n    marquee: Boolean(document.querySelector(".file-marquee")),\n    selected: [...el.querySelectorAll(".file-tile.selected")].map((node) => node.getAttribute("data-path")),\n    cwd: el.getAttribute("data-pane-cwd"),\n  }))));\n  await expect(firstPane.locator(".filepane-selectionbar")).toContainText("2 项已选");\n'''
count = text.count(old)
if count != 1:
    raise RuntimeError(f"expected one marquee test block, found {count}")
path.write_text(text.replace(old, new, 1), encoding="utf-8")
print("file marquee v5 diagnostics staged")
